namespace FiveStar.Shaders.Dxil.Ir;

/// <summary>LLVM binary operator codes; the float forms share the integer codes (add is fadd on floats).</summary>
public enum BinaryOp
{
    Add = 0,
    Sub = 1,
    Mul = 2,
    UDiv = 3,
    SDiv = 4,
    URem = 5,
    SRem = 6,
    Shl = 7,
    LShr = 8,
    AShr = 9,
    And = 10,
    Or = 11,
    Xor = 12,
}
